# Prepared actual full-runtime Renditions.ensure caller. Run not executed.
alias Barkpark.{Media, Repo}
alias Barkpark.Media.{Renditions, ImageBackend}
alias Barkpark.Media.Storage.MediaFile
alias Barkpark.Plugins.Media.Assets
output = System.fetch_env!("C108_CHECKOUT_OUTPUT")
write = fn name, value ->
  path = Path.join(output, name <> ".json")
  File.write!(path <> ".writing", JSON.encode!(value), [:exclusive])
  File.rename!(path <> ".writing", path)
end
await = fn name ->
  deadline = System.monotonic_time(:millisecond) + 90_000
  Stream.repeatedly(fn ->
    cond do
      File.exists?(Path.join(output, name)) -> true
      System.monotonic_time(:millisecond) >= deadline -> raise("Rendition caller marker timeout: #{name}")
      File.exists?(Path.join(output, "native-trace-failed.json")) -> raise("Actual native trace failed")
      File.exists?(Path.join(output, "native-observer-failed.json")) -> raise("Actual native observer failed")
      true -> Process.sleep(20); false
    end
  end) |> Enum.find(& &1)
end
started = System.monotonic_time(:millisecond)
try do
  await.("setup-go")
  backend = ImageBackend.impl()
  true = backend == Barkpark.Media.ImageBackend.Magick
  original_config = Application.get_env(:barkpark, backend)
  value = try do
    Application.put_env(:barkpark, backend, Keyword.put(original_config || [], :bin, System.fetch_env!("C108_IMAGE_BIN")))
    true = backend.available?()
    [[workspace, project, dataset]] = Ecto.Adapters.SQL.query!(Repo, "SELECT w.id::text,p.id::text,d.slug FROM workspaces w JOIN projects p ON p.workspace_id=w.id JOIN datasets d ON d.project_id=p.id WHERE w.is_default AND p.slug='default' ORDER BY d.slug LIMIT 1", []).rows
    input = Path.join(output, "original.png")
    payload = Base.decode64!("")
    File.write!(input, payload, [:exclusive])
    {:ok, %MediaFile{} = file} = Media.upload(%Plug.Upload{path: input, filename: "caller.png", content_type: "image/png"}, dataset, workspace_id: workspace, project_id: project)
    "image/png" = file.mime_type
    {:ok, asset} = Assets.ensure_for_upload(file)
    row = Repo.get!(MediaFile, file.id)
    source = Media.file_path(file.path)
    ^payload = File.read!(source)
    rel = Path.join(["_renditions", file.id, "thumb.jpg"])
    destination = Media.file_path(rel)
    false = File.exists?(destination)
    nil = Renditions.relative_path(file, "thumb")
    write.("caller-ready", %{media: Media.upload_dir(), file: Map.take(file, [:id, :path, :mime_type, :workspace_id, :project_id, :dataset]), source: source, expected: destination, relative: rel, asset_revision: asset.rev, cold: true, source_sha256: Base.encode16(:crypto.hash(:sha256, payload), case: :lower)})
    await.("trace-go")
    tracer = Barkdown.PrivateNativePortTrace.arm(output, System.fetch_env!("C108_IMAGE_BIN"))
    Process.put(:c108_owned_trace, tracer)
    write.("trace-ready", %{status: "armed", beam_os_pid: System.pid()})
    await.("render-go")
    false = File.exists?(destination)
    parent = self()
    worker = spawn(fn ->
      receive do :owned_go -> :ok after 10_000 -> raise "Owned caller start timeout" end
      returned = Renditions.ensure(file, "thumb")
      send(parent, {:owned_caller_returned, self(), returned})
    end)
    reference = Process.monitor(worker)
    write.("worker-ready", %{status: "owned_worker_waiting", caller: inspect(worker), monitor: inspect(reference)})
    await.("worker-go")
    send(worker, :owned_go)
    await.("kill-caller")
    receive do {:owned_caller_returned, ^worker, returned} -> raise("Caller returned before owned interruption: #{inspect(returned)}") after 0 -> :ok end
    true = Process.alive?(worker)
    Process.exit(worker, :kill)
    receive do
      {:DOWN, ^reference, :process, ^worker, :killed} -> :ok
      {:DOWN, ^reference, :process, ^worker, reason} -> raise("Unexpected owned caller DOWN: #{inspect(reason)}")
    after 5_000 -> raise("Matching owned caller DOWN absent")
    end
    receive do {:owned_caller_returned, ^worker, returned} -> raise("Caller returned before DOWN: #{inspect(returned)}") after 0 -> :ok end
    write.("owner-down", %{status: "actual_owned_caller_down", caller: inspect(worker), monitor: inspect(reference), reason: "killed", returned: false, observed_at: DateTime.utc_now() |> DateTime.to_iso8601()})
    await.("native-at-owner-down.json")
    await.("native-port-closed.json")
    await.("native-exit.json")
    true = Repo.get!(MediaFile, file.id) == row
    true = Assets.find_by_media_file_id(file.id, dataset, MediaFile.scope_opts(file)) == asset
    ^payload = File.read!(source)
    children = case File.ls(Path.dirname(destination)) do {:ok, names} -> names; {:error, :enoent} -> [] end
    %{status: "actual_native_caller_loss_observed", returned: "killed", relative: rel, source: source, destination: destination, source_sha256: Base.encode16(:crypto.hash(:sha256, payload), case: :lower), destination_exists: File.exists?(destination), children: children, row_unchanged: true, asset_unchanged: true}
  after
    if tracer = Process.delete(:c108_owned_trace), do: Barkdown.PrivateNativePortTrace.disarm(tracer)
    if is_nil(original_config), do: Application.delete_env(:barkpark, backend), else: Application.put_env(:barkpark, backend, original_config)
  end
  true = Application.get_env(:barkpark, backend) == original_config
  write.("caller-result", Map.put(value, :config_restored, true))
  await.("render-reviewed")
  write.("result", %{status: "actual_native_caller_loss_completed", elapsedMs: System.monotonic_time(:millisecond) - started})
rescue
  e -> write.("result", %{status: "failed", error: Exception.format(:error, e, __STACKTRACE__), elapsedMs: System.monotonic_time(:millisecond) - started})
end
